// May run with m.p==nil, so write barriers are not allowed.
//
//go:nowritebarrierrec
func windows_newosproc(mp *m) {
	// LockOSThread can reach newosproc on a goroutine stack when starting
	// the template thread. createThread does not switch stacks itself.
	var thandle uintptr
	var err uint32
	systemstack(func() {
		thandle, err = windows_createThread(0, unsafe.Pointer(abi.FuncPCABI0(windows_tstart_stdcall)), unsafe.Pointer(mp))
	})
	if thandle == 0 {
		if atomic.Load(&windows_exiting) != 0 {
			// CreateThread may fail if called
			// concurrently with ExitProcess. If this
			// happens, just freeze this thread and let
			// the process exit. See issue #18253.
			lock(&deadlock)
			lock(&deadlock)
		}
		print("runtime: failed to create new OS thread (have ", mcount(), " already; errno=", err, ")\n")
		throw("runtime.newosproc")
	}

	// Close thandle to avoid leaking the thread object if it exits.
	windows_stdcall(windows__CloseHandle, thandle)
}

// Used by the C library build mode. On Linux this function would allocate a
// stack, but that's not necessary for Windows. No stack guards are present
// and the GC has not been initialized, so write barriers will fail.
//
//go:nowritebarrierrec
//go:nosplit
func windows_newosproc0(stacksize uintptr, fn unsafe.Pointer) {
	thandle, err := windows_createThread(stacksize, fn, nil)
	if thandle == 0 {
		print("runtime: failed to create new OS thread (errno=", err, ")\n")
		throw("runtime: failed to create new OS thread\n")
	}
	windows_stdcall_no_g(windows__CloseHandle, thandle)
}

// createThread calls CreateThread to create a new thread.
//
//go:nowritebarrierrec
//go:nosplit
func windows_createThread(stackSize uintptr, fn unsafe.Pointer, arg unsafe.Pointer) (handle uintptr, err uint32) {
	for tries := range 20 {
		// We pass 0 for the stack size to use the default for this binary.
		handle = windows_stdcall_no_g(windows__CreateThread, 0, stackSize, uintptr(fn), uintptr(arg), 0, 0)
		if handle == 0 {
			err = windows_getlasterror()
		}
		if handle == 0 && err == windows.Windows_ERROR_ACCESS_DENIED {
			// "Insufficient resources". Yield, then back off a bit before retrying.
			windows_usleep_no_g(uint32(tries) * 1000)
			continue
		}
		break
	}
	return handle, err
}

