// Called to initialize a new m (including the bootstrap m).
// Called on the new thread, cannot allocate Go memory.
func windows_minit() {
	var thandle uintptr
	if windows_stdcall(windows__DuplicateHandle, windows.Windows_CurrentProcess, windows.Windows_CurrentThread, windows.Windows_CurrentProcess, uintptr(unsafe.Pointer(&thandle)), 0, 0, windows.Windows_DUPLICATE_SAME_ACCESS) == 0 {
		print("runtime.minit: duplicatehandle failed; errno=", windows_getlasterror(), "\n")
		throw("runtime.minit: duplicatehandle failed")
	}

	mp := getg().m
	lock(&mp.windows_threadLock)
	mp.windows_thread = thandle
	mp.procid = uint64(windows_stdcall(windows__GetCurrentThreadId))

	// Configure usleep timer, if possible.
	if mp.windows_highResTimer == 0 && windows_haveHighResTimer {
		mp.windows_highResTimer = windows_createHighResTimer()
		if mp.windows_highResTimer == 0 {
			print("runtime: CreateWaitableTimerEx failed; errno=", windows_getlasterror(), "\n")
			throw("CreateWaitableTimerEx when creating timer failed")
		}
	}
	if mp.windows_waitIocpHandle == 0 && windows_haveHighResSleep {
		mp.windows_waitIocpTimer = windows_createHighResTimer()
		if mp.windows_waitIocpTimer == 0 {
			print("runtime: CreateWaitableTimerEx failed; errno=", windows_getlasterror(), "\n")
			throw("CreateWaitableTimerEx when creating timer failed")
		}
		const GENERIC_ALL = 0x10000000
		errno := windows_stdcall(windows__NtCreateWaitCompletionPacket, uintptr(unsafe.Pointer(&mp.windows_waitIocpHandle)), GENERIC_ALL, 0)
		if mp.windows_waitIocpHandle == 0 {
			print("runtime: NtCreateWaitCompletionPacket failed; errno=", errno, "\n")
			throw("NtCreateWaitCompletionPacket failed")
		}
	}
	unlock(&mp.windows_threadLock)

	// Query the true stack base from the OS. Currently we're
	// running on a small assumed stack.
	var mbi windows.Windows_MemoryBasicInformation
	res := windows_stdcall(windows__VirtualQuery, uintptr(unsafe.Pointer(&mbi)), uintptr(unsafe.Pointer(&mbi)), unsafe.Sizeof(mbi))
	if res == 0 {
		print("runtime: VirtualQuery failed; errno=", windows_getlasterror(), "\n")
		throw("VirtualQuery for stack base failed")
	}
	// The system leaves an 8K PAGE_GUARD region at the bottom of
	// the stack (in theory VirtualQuery isn't supposed to include
	// that, but it does). Add an additional 8K of slop for
	// calling C functions that don't have stack checks and for
	// lastcontinuehandler. We shouldn't be anywhere near this
	// bound anyway.
	base := mbi.AllocationBase + 16<<10
	// Sanity check the stack bounds.
	g0 := getg()
	if base > g0.stack.hi || g0.stack.hi-base > 64<<20 {
		print("runtime: g0 stack [", hex(base), ",", hex(g0.stack.hi), ")\n")
		throw("bad g0 stack")
	}
	g0.stack.lo = base
	g0.stackguard0 = g0.stack.lo + stackGuard
	g0.stackguard1 = g0.stackguard0
	// Sanity check the SP.
	stackcheck()
}

// Called from dropm to undo the effect of an minit.
//
//go:nosplit
func windows_unminit() {
	mp := getg().m
	lock(&mp.windows_threadLock)
	if mp.windows_thread != 0 {
		windows_stdcall(windows__CloseHandle, mp.windows_thread)
		mp.windows_thread = 0
	}
	unlock(&mp.windows_threadLock)

	mp.procid = 0
}

// Called from mexit, but not from dropm, to undo the effect of thread-owned
// resources in minit, semacreate, or elsewhere. Do not take locks after calling this.
//
// This always runs without a P, so //go:nowritebarrierrec is required.
//
//go:nowritebarrierrec
//go:nosplit
func windows_mdestroy(mp *m) {
	if mp.windows_highResTimer != 0 {
		windows_stdcall(windows__CloseHandle, mp.windows_highResTimer)
		mp.windows_highResTimer = 0
	}
	if mp.windows_waitIocpTimer != 0 {
		windows_stdcall(windows__CloseHandle, mp.windows_waitIocpTimer)
		mp.windows_waitIocpTimer = 0
	}
	if mp.windows_waitIocpHandle != 0 {
		windows_stdcall(windows__CloseHandle, mp.windows_waitIocpHandle)
		mp.windows_waitIocpHandle = 0
	}
	if mp.windows_waitsema != 0 {
		windows_stdcall(windows__CloseHandle, mp.windows_waitsema)
		mp.windows_waitsema = 0
	}
	if mp.windows_resumesema != 0 {
		windows_stdcall(windows__CloseHandle, mp.windows_resumesema)
		mp.windows_resumesema = 0
	}
}

// stdcall_no_g is like [stdcall] but can be called without a G.
//
//go:nowritebarrier
//go:nosplit
//go:uintptrkeepalive
func windows_stdcall_no_g(fn windows_stdFunction, args ...uintptr) uintptr {
	call := windows.Windows_StdCallInfo{
		Fn: uintptr(unsafe.Pointer(fn)),
		N:  uintptr(len(args)),
	}
	if len(args) > 0 {
		call.Args = uintptr(abi.NoEscape(unsafe.Pointer(&args[0])))
	}
	windows.Windows_StdCall(&call)
	return call.R1
}

// stdcall calls fn with the given arguments using the stdcall calling convention.
// Must be called from the system stack.
// May run during STW, so write barriers are not allowed.
//
//go:nowritebarrier
//go:nosplit
//go:uintptrkeepalive
func windows_stdcall(fn windows_stdFunction, args ...uintptr) uintptr {
	gp := getg()
	mp := gp.m
	mp.windows_stdCallInfo.Fn = uintptr(unsafe.Pointer(fn))
	mp.windows_stdCallInfo.N = uintptr(len(args))
	if len(args) > 0 {
		mp.windows_stdCallInfo.Args = uintptr(abi.NoEscape(unsafe.Pointer(&args[0])))
	}
	resetLibcall := false
	if mp.profilehz != 0 && mp.libcallsp == 0 {
		// leave pc/sp for cpu profiler
		mp.libcallg.set(gp)
		mp.libcallpc = sys.GetCallerPC()
		// sp must be the last, because once async cpu profiler finds
		// all three values to be non-zero, it will use them
		mp.libcallsp = sys.GetCallerSP()
		resetLibcall = true // See comment in sys_darwin.go:libcCall
	}
	asmcgocall(windows_asmstdcallAddr, unsafe.Pointer(&mp.windows_stdCallInfo))
	if resetLibcall {
		mp.libcallsp = 0
	}
	return mp.windows_stdCallInfo.R1
}

