//go:nosplit
func windows_usleep_no_g(us uint32) {
	timeout := uintptr(us) / 1000 // ms units
	windows_stdcall_no_g(windows__WaitForSingleObject, windows.Windows_INVALID_HANDLE_VALUE, timeout)
}

//go:nosplit
func windows_usleep(us uint32) {
	systemstack(func() {
		var h, timeout uintptr
		// If the high-res timer is available and its handle has been allocated for this m, use it.
		// Otherwise fall back to the low-res one, which doesn't need a handle.
		if windows_haveHighResTimer && getg().m.windows_highResTimer != 0 {
			h = getg().m.windows_highResTimer
			dt := -10 * int64(us) // relative sleep (negative), 100ns units
			windows_stdcall(windows__SetWaitableTimer, h, uintptr(unsafe.Pointer(&dt)), 0, 0, 0, 0)
			timeout = windows.Windows_INFINITE
		} else {
			h = windows.Windows_INVALID_HANDLE_VALUE
			timeout = uintptr(us) / 1000 // ms units
		}
		windows_stdcall(windows__WaitForSingleObject, h, timeout)
	})
}

func windows_ctrlHandler(_type uint32) uintptr {
	var s uint32

	switch _type {
	case windows.Windows_CTRL_C_EVENT, windows.Windows_CTRL_BREAK_EVENT:
		s = windows.Windows_SIGINT
	case windows.Windows_CTRL_CLOSE_EVENT, windows.Windows_CTRL_LOGOFF_EVENT, windows.Windows_CTRL_SHUTDOWN_EVENT:
		s = windows.Windows_SIGTERM
	default:
		return 0
	}

	if sigsend(s) {
		if s == windows.Windows_SIGTERM {
			// Windows terminates the process after this handler returns.
			// Block indefinitely to give signal handlers a chance to clean up,
			// but make sure to be properly parked first, so the rest of the
			// program can continue executing.
			block()
		}
		return 1
	}
	return 0
}

// called from zcallback_windows_*.s to sys_windows_*.s
func windows_callbackasm1()

var windows_profiletimer uintptr

func windows_profilem(mp *m, thread uintptr) {
	// Align Context to 16 bytes.
	var c *windows.Windows_Context
	var cbuf [unsafe.Sizeof(*c) + 15]byte
	c = (*windows.Windows_Context)(unsafe.Pointer((uintptr(unsafe.Pointer(&cbuf[15]))) &^ 15))

	c.ContextFlags = windows.Windows_CONTEXT_CONTROL
	windows_stdcall(windows__GetThreadContext, thread, uintptr(unsafe.Pointer(c)))

	gp := windows_gFromSP(mp, c.SP())

	sigprof(c.PC(), c.SP(), c.LR(), gp, mp)
}

func windows_gFromSP(mp *m, sp uintptr) *g {
	if gp := mp.g0; gp != nil && gp.stack.lo < sp && sp < gp.stack.hi {
		return gp
	}
	if gp := mp.gsignal; gp != nil && gp.stack.lo < sp && sp < gp.stack.hi {
		return gp
	}
	if gp := mp.curg; gp != nil && gp.stack.lo < sp && sp < gp.stack.hi {
		return gp
	}
	return nil
}

func windows_profileLoop() {
	windows_stdcall(windows__SetThreadPriority, windows.Windows_CurrentThread, windows.Windows_THREAD_PRIORITY_HIGHEST)

	for {
		windows_stdcall(windows__WaitForSingleObject, windows_profiletimer, windows.Windows_INFINITE)
		first := (*m)(atomic.Loadp(unsafe.Pointer(&allm)))
		for mp := first; mp != nil; mp = mp.alllink {
			if mp == getg().m {
				// Don't profile ourselves.
				continue
			}

			lock(&mp.windows_threadLock)
			// Do not profile threads blocked on Notes,
			// this includes idle worker threads,
			// idle timer thread, idle heap scavenger, etc.
			if mp.windows_thread == 0 || mp.profilehz == 0 || mp.blocked {
				unlock(&mp.windows_threadLock)
				continue
			}
			// Acquire our own handle to the thread.
			var thread uintptr
			if windows_stdcall(windows__DuplicateHandle, windows.Windows_CurrentProcess, mp.windows_thread, windows.Windows_CurrentProcess, uintptr(unsafe.Pointer(&thread)), 0, 0, windows.Windows_DUPLICATE_SAME_ACCESS) == 0 {
				print("runtime: duplicatehandle failed; errno=", windows_getlasterror(), "\n")
				throw("duplicatehandle failed")
			}
			unlock(&mp.windows_threadLock)

			// mp may exit between the DuplicateHandle
			// above and the SuspendThread. The handle
			// will remain valid, but SuspendThread may
			// fail.
			if int32(windows_stdcall(windows__SuspendThread, thread)) == -1 {
				// The thread no longer exists.
				windows_stdcall(windows__CloseHandle, thread)
				continue
			}
			if mp.profilehz != 0 && !mp.blocked {
				// Pass the thread handle in case mp
				// was in the process of shutting down.
				windows_profilem(mp, thread)
			}
			windows_stdcall(windows__ResumeThread, thread)
			windows_stdcall(windows__CloseHandle, thread)
		}
	}
}

func windows_setProcessCPUProfiler(hz int32) {
	if windows_profiletimer == 0 {
		var timer uintptr
		if windows_haveHighResTimer {
			timer = windows_createHighResTimer()
		} else {
			timer = windows_stdcall(windows__CreateWaitableTimerA, 0, 0, 0)
		}
		atomic.Storeuintptr(&windows_profiletimer, timer)
		newm(windows_profileLoop, nil, -1)
	}
}

func windows_setThreadCPUProfiler(hz int32) {
	ms := int32(0)
	due := ^int64(^uint64(1 << 63))
	if hz > 0 {
		ms = 1000 / hz
		if ms == 0 {
			ms = 1
		}
		due = int64(ms) * -10000
	}
	windows_stdcall(windows__SetWaitableTimer, windows_profiletimer, uintptr(unsafe.Pointer(&due)), uintptr(ms), 0, 0, 0)
	atomic.Store((*uint32)(unsafe.Pointer(&getg().m.profilehz)), uint32(hz))
}

const windows_preemptMSupported = true

// suspendLock protects simultaneous SuspendThread operations from
// suspending each other.
var windows_suspendLock mutex

// threadPausedLockRank warns the runtime against acquiring new locks on this
// thread while it has another thread paused. The holder of this lock rank is
// effectively a signal handler for a paused thread, which may be holding
// arbitrary locks.
//
// The warning takes two concrete forms: First, unlock2 will see that this
// thread is holding other locks, so won't try to flush the mutex contention
// buffer (which can involve acquiring another lock). Second, builds with
// GOEXPERIMENT=staticlockranking (currently broken, https://go.dev/issue/76058)
// will report a rank violation.
//
// suspendLock serializes the transition into "suspended", but it's fine for
// multiple threads to be in the suspended state concurrently, with each of
// their sponsors independently using threadPausedLockRank to discourage
// themselves from acquiring new locks.
const windows_threadPausedLockRank = lockRankLeafRank

func windows_preemptM(mp *m) {
	if mp == getg().m {
		throw("self-preempt")
	}

	// Synchronize with external code that may try to ExitProcess.
	if !atomic.Cas(&mp.windows_preemptExtLock, 0, 1) {
		// External code is running. Fail the preemption
		// attempt.
		mp.preemptGen.Add(1)
		return
	}

	// Acquire our own handle to mp's thread.
	lock(&mp.windows_threadLock)
	if mp.windows_thread == 0 {
		// The M hasn't been minit'd yet (or was just unminit'd).
		unlock(&mp.windows_threadLock)
		atomic.Store(&mp.windows_preemptExtLock, 0)
		mp.preemptGen.Add(1)
		return
	}
	var thread uintptr
	if windows_stdcall(windows__DuplicateHandle, windows.Windows_CurrentProcess, mp.windows_thread, windows.Windows_CurrentProcess, uintptr(unsafe.Pointer(&thread)), 0, 0, windows.Windows_DUPLICATE_SAME_ACCESS) == 0 {
		print("runtime.preemptM: duplicatehandle failed; errno=", windows_getlasterror(), "\n")
		throw("runtime.preemptM: duplicatehandle failed")
	}
	unlock(&mp.windows_threadLock)

	// Prepare thread context buffer. This must be aligned to 16 bytes.
	var c *windows.Windows_Context
	var cbuf [unsafe.Sizeof(*c) + 15]byte
	c = (*windows.Windows_Context)(unsafe.Pointer((uintptr(unsafe.Pointer(&cbuf[15]))) &^ 15))
	c.ContextFlags = windows.Windows_CONTEXT_CONTROL

	// Serialize thread suspension. SuspendThread is asynchronous,
	// so it's otherwise possible for two threads to suspend each
	// other and deadlock. We must hold this lock until after
	// GetThreadContext, since that blocks until the thread is
	// actually suspended.
	lock(&windows_suspendLock)

	// Signal handler rules are in effect; don't acquire new locks.
	acquireLockRankAndM(windows_threadPausedLockRank)

	// Suspend the thread.
	if int32(windows_stdcall(windows__SuspendThread, thread)) == -1 {
		unlock(&windows_suspendLock)
		windows_stdcall(windows__CloseHandle, thread)
		atomic.Store(&mp.windows_preemptExtLock, 0)
		// The thread no longer exists. This shouldn't be
		// possible, but just acknowledge the request.
		mp.preemptGen.Add(1)
		releaseLockRankAndM(windows_threadPausedLockRank)
		return
	}

	// We have to be very careful between this point and once
	// we've shown mp is at an async safe-point. This is like a
	// signal handler in the sense that mp could have been doing
	// anything when we stopped it, including holding arbitrary
	// locks.

	// We have to get the thread context before inspecting the M
	// because SuspendThread only requests a suspend.
	// GetThreadContext actually blocks until it's suspended.
	windows_stdcall(windows__GetThreadContext, thread, uintptr(unsafe.Pointer(c)))

	unlock(&windows_suspendLock)

	// Does it want a preemption and is it safe to preempt?
	gp := windows_gFromSP(mp, c.SP())
	if gp != nil && wantAsyncPreempt(gp) {
		if ok, resumePC := isAsyncSafePoint(gp, c.PC(), c.SP(), c.LR()); ok {
			// Inject call to asyncPreempt
			targetPC := abi.FuncPCABI0(asyncPreempt)
			c.PushCall(targetPC, resumePC)
			windows_stdcall(windows__SetThreadContext, thread, uintptr(unsafe.Pointer(c)))
		}
	}

	atomic.Store(&mp.windows_preemptExtLock, 0)

	// Acknowledge the preemption.
	mp.preemptGen.Add(1)

	windows_stdcall(windows__ResumeThread, thread)
	windows_stdcall(windows__CloseHandle, thread)

	releaseLockRankAndM(windows_threadPausedLockRank)
}

// osPreemptExtEnter is called before entering external code that may
// call ExitProcess.
//
// This must be nosplit because it may be called from a syscall with
// untyped stack slots, so the stack must not be grown or scanned.
//
//go:nosplit
func windows_osPreemptExtEnter(mp *m) {
	for !atomic.Cas(&mp.windows_preemptExtLock, 0, 1) {
		// An asynchronous preemption is in progress. It's not
		// safe to enter external code because it may call
		// ExitProcess and deadlock with SuspendThread.
		// Ideally we would do the preemption ourselves, but
		// can't since there may be untyped syscall arguments
		// on the stack. Instead, just wait and encourage the
		// SuspendThread APC to run. The preemption should be
		// done shortly.
		windows_osyield()
	}
	// Asynchronous preemption is now blocked.
}

// osPreemptExtExit is called after returning from external code that
// may call ExitProcess.
//
// See osPreemptExtEnter for why this is nosplit.
//
//go:nosplit
func windows_osPreemptExtExit(mp *m) {
	atomic.Store(&mp.windows_preemptExtLock, 0)
}
